import operator


def plan_batch(jobs: list[tuple[str, int, int, int]]) -> tuple[int, list[str]]:
    """
    Choose a feasible set of jobs to finish on time that minimizes the total
    SLA penalty owed for late jobs.

    The key facts used:
      * If a set of jobs can all be on time, running them in nondecreasing
        deadline order is also feasible.
      * Therefore we sort by deadline and use a pseudo-polynomial DP over
        total elapsed time, maximizing the penalties avoided.
    """
    seen = set()
    total_penalty = 0
    candidates = []

    for job in jobs:
        try:
            job_id, duration, deadline, penalty = job
        except (TypeError, ValueError):
            raise ValueError(
                "each job must be a (job_id, duration, deadline, penalty) tuple"
            ) from None

        try:
            if job_id in seen:
                raise ValueError("duplicate job id")
            seen.add(job_id)
        except TypeError:
            raise ValueError("job_id must be hashable") from None

        try:
            duration = operator.index(duration)
            deadline = operator.index(deadline)
            penalty = operator.index(penalty)
        except TypeError:
            raise ValueError(
                "duration, deadline, and penalty must be integers"
            ) from None

        if duration < 1:
            raise ValueError("duration must be at least 1")
        if deadline < 0:
            raise ValueError("deadline must be non-negative")
        if penalty < 0:
            raise ValueError("penalty must be non-negative")

        total_penalty += penalty

        # A job with penalty 0 never needs to be listed.
        # A job whose duration exceeds its deadline can never be on time.
        if penalty > 0 and deadline >= duration:
            candidates.append((deadline, duration, penalty, job_id))

    if not candidates:
        return (total_penalty, [])

    # Earliest-deadline-first order is sufficient for feasibility checking.
    candidates.sort(key=lambda item: (item[0], item[1]))

    max_deadline = candidates[-1][0]
    total_duration = sum(item[1] for item in candidates)
    max_time = max_deadline if max_deadline < total_duration else total_duration

    # dp[t] = maximum penalty avoided by a feasible on-time subset
    #         with total duration exactly t.
    # masks[t] stores the selected jobs for that best subset as a bitmask.
    dp = [-1] * (max_time + 1)
    masks = [0] * (max_time + 1)
    dp[0] = 0

    for idx, (deadline, duration, penalty, _) in enumerate(candidates):
        if duration > max_time:
            continue

        limit = deadline if deadline < max_time else max_time
        if limit < duration:
            continue

        bit = 1 << idx

        # Traverse backwards so each job is used at most once.
        for t in range(limit - duration, -1, -1):
            current = dp[t]
            if current != -1:
                new_time = t + duration
                new_value = current + penalty
                if new_value > dp[new_time]:
                    dp[new_time] = new_value
                    masks[new_time] = masks[t] | bit

    best_time = 0
    best_saved = dp[0]
    for t in range(1, max_time + 1):
        if dp[t] > best_saved:
            best_saved = dp[t]
            best_time = t

    if best_saved == 0:
        return (total_penalty, [])

    mask = masks[best_time]
    on_time_order = [
        item[3]
        for idx, item in enumerate(candidates)
        if mask & (1 << idx)
    ]

    return (total_penalty - best_saved, on_time_order)
